import { chromium } from 'playwright';
let browser = null;
let page = null;
export async function browserSigner(url) {
    let localBrowser = null;
    try {
        localBrowser = await chromium.launch({ headless: true });
        const localPage = await localBrowser.newPage();
        await localPage.goto('https://www.tiktok.com', { waitUntil: 'networkidle', timeout: 20000 });
        await localPage.waitForTimeout(2000);
        const sig = await localPage.evaluate((u) => {
            const signer = window.byted_acrawler?.sign;
            return typeof signer === 'function' ? signer(u) : null;
        }, url);
        return sig || null;
    }
    catch (e) {
        console.error('❌ browserSigner error:', e);
        return null;
    }
    finally {
        if (localBrowser)
            await localBrowser.close();
    }
}
export async function embeddedSignerInit() {
    browser = await chromium.launch({ headless: true });
    page = await browser.newPage();
    await page.goto('https://www.tiktok.com', { waitUntil: 'networkidle', timeout: 20000 });
    await page.waitForTimeout(2000);
    return {
        sign: async (url) => {
            if (!page)
                throw new Error('embeddedSigner: page is null');
            const sig = await page.evaluate((u) => {
                const signer = window.byted_acrawler?.sign;
                return typeof signer === 'function' ? signer(u) : null;
            }, url);
            if (!sig)
                throw new Error('embeddedSigner.sign() not available');
            return sig;
        },
        close: async () => {
            if (browser)
                await browser.close();
            browser = null;
            page = null;
        }
    };
}
